// GQ cannot aggregate over an aggregate, so a per-company count cannot be averaged in one query.
// This returns only the largest headcount (top company); the mean is not expressible here.
query company_headcount() {
    match {
        $c: Company
        $p worksAt $c
    }
    return {
        $c.name
        count($p) as largest
    }
    order { largest desc }
    limit 1
}
